package cn.huankan.collector;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.net.URI;
class GleifIdentityTest {
 @Test void exactLeiCheckDigitRejectsTypoAndUntrustedEndpoints(){assertTrue(GleifService.validLei("HWUPKR0MPOU8FGXBT394"));assertFalse(GleifService.validLei("HWUPKR0MPOU8FGXBT395"));assertFalse(GleifService.validLei("Apple Inc."));OfficialHttpClient.validate(URI.create("https://api.gleif.org/api/v1/lei-records/HWUPKR0MPOU8FGXBT394"));assertThrows(IllegalArgumentException.class,()->OfficialHttpClient.validate(URI.create("https://api.gleif.org.evil.test/api/v1/lei-records/HWUPKR0MPOU8FGXBT394")));assertThrows(IllegalArgumentException.class,()->OfficialHttpClient.validate(URI.create("https://api.gleif.org/api/v1/lei-records?page%5Bsize%5D=10000")));}
 @Test void deterministicRulesDoNotConfuseReferenceFxAndPolicy(){assertEquals("REFERENCE_FX",cn.huankan.event.ImpactService.rule("MACRO_OBSERVATION","EXR.D.USD.EUR.SP00.A",""));assertEquals("POLICY",cn.huankan.event.ImpactService.rule("MACRO_OBSERVATION","FM.B.U2.EUR.4F.KR.DFR.LEV",""));assertEquals("INFLATION",cn.huankan.event.ImpactService.rule("OFFICIAL_PUBLICATION","","居民消费价格发布"));assertEquals("CAPEX",cn.huankan.event.ImpactService.rule("BUSINESS_ANNOUNCEMENT","","capital expenditure"));assertEquals("DISCLOSURE",cn.huankan.event.ImpactService.rule("FINANCIAL_DISCLOSURE","",""));assertEquals("PUBLICATION",cn.huankan.event.ImpactService.rule("OFFICIAL_PUBLICATION","","A title is not a proven supplier relationship"));}
}
